"""Rebuild the static Cloudflare Worker from Python gameplay and browser HTML."""
from pathlib import Path
import json

root = Path(__file__).resolve().parents[1]
html_path = root / 'web' / 'index.html'
py = (root / 'web' / 'game.py').read_text(encoding='utf-8').rstrip('\n')
html = html_path.read_text(encoding='utf-8')

start = '<script type="text/plain" id="python-source">\n'
i = html.index(start) + len(start)
j = html.index('\n</script>', i)
html = html[:i] + py + html[j:]
html_path.write_text(html, encoding='utf-8')

worker = (
    '// Generated by scripts/build_worker.py. POT BREAKER RE v1.0.0\n'
    + 'const PAGE=' + json.dumps(html, ensure_ascii=False) + ';\n'
    + "export default {async fetch(request){const u=new URL(request.url);"
    + "if(u.pathname==='/health')return new Response(JSON.stringify({ok:true,version:'1.0.0',engine:'Python/Pyodide'}),"
    + "{headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});"
    + "if(u.pathname!=='/'&&u.pathname!=='/index.html')return new Response('Not Found',{status:404});"
    + "return new Response(PAGE,{headers:{'content-type':'text/html; charset=utf-8',"
    + "'cache-control':'public, max-age=60','x-content-type-options':'nosniff'}})}};"
)
(root / 'cloudflare' / 'worker.js').write_text(worker, encoding='utf-8')
print('Updated web/index.html and cloudflare/worker.js')
